    /** 展示和检索分别服从固定模板，历史列表不批量展开完整快照。 */
    
    /** 复核与撤回竞争时只有一个终态胜出，不形成反向加锁或半生效。 */
    

    /** 待审期间目的盒撤下，旧申请不得把文件移入已停用范围。 */
    
    /** 构造已开放安全题名的真实借阅，推进到允许补录的负责人节点。 */
    private UUID consentStep() throws Exception {UUID record=published("IMPORTANT",b);policy(record,false,List.of());UUID batch=submitBorrow(applicant,List.of(record));UUID flow=(UUID)db.required("SELECT workflow_instance_id FROM archive.borrow_request WHERE batch_id=?",batch).get("workflow_instance_id");for(int i=0;i<8;i++){var step=db.required("SELECT s.* FROM workflow.step s JOIN workflow.instance w ON w.current_step_id=s.id WHERE w.id=?",flow);if(Set.of("DEPARTMENT_MANAGER","GENERAL_MANAGER").contains(step.get("duty_code")))return (UUID)step.get("id");workflow.decide(context(actors.get(step.get("assignee_id")),"WORKFLOW_STEP",(UUID)step.get("id"),"DECIDE_STEP",((Number)step.get("row_version")).intValue()),(UUID)step.get("id"),Sql.map("result","APPROVE","comment","已核对前置必要节点"));}throw new AssertionError("未到达可补录节点");}
    /** 真实上传合并和原生扫描；不会直接把原件状态改为可用。 */
    private UUID evidenceObject(UUID step) throws Exception {byte[] content=Files.readAllBytes(Path.of(System.getenv("IMS_DRIVE_TEST_PDF")));String hash=HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(content));UUID request=UUID.randomUUID();UUID upload=(UUID)uploads.create(applicant,Sql.map("module","ARCHIVE","businessContextId",step.toString(),"purpose","EVIDENCE","originalName","同意凭据.pdf","expectedSize",content.length,"expectedSha256",hash,"expectedMediaType","application/pdf"),UUID.randomUUID(),request).get("uploadId");uploads.part(applicant,upload,1,"bytes 0-"+(content.length-1)+"/"+content.length,content.length,hash,new ByteArrayInputStream(content),request);UUID job=(UUID)uploads.complete(applicant,upload,Sql.map("partCount",1,"finalSha256",hash),UUID.randomUUID(),request).get("jobId");assembly.assemble(applicant,job,request);inspection.inspect(applicant,job,request);assertEquals("COMPLETE",uploads.get(applicant,upload).get("state"));return (UUID)uploads.get(applicant,upload).get("objectId");}
    /** 提交与核验使用同一实际时间和固定原件清单。 */
    private Map<String,Object> submission(UUID step) throws Exception {UUID object=evidenceObject(step);var node=db.required("SELECT * FROM workflow.step WHERE id=?",step);return consent.submit(new Commands.Context(applicant,UUID.randomUUID(),UUID.randomUUID(),"TEST SUBMIT_EVIDENCE",null,((Number)node.get("row_version")).intValue()),step,Sql.map("originalApproverId",node.get("assignee_id").toString(),"agreedAt",Instant.now().truncatedTo(java.time.temporal.ChronoUnit.MICROS).toString(),"objectIds",List.of(object.toString()),"description","已核对固定文件版本、动作及期限的同意记录"));}
    private Map<String,Object> decisionBody(Map<String,Object> submitted) {return Sql.map("evidenceIds",((List<?>)submitted.get("evidence")).stream().map(x->((Map<?,?>)x).get("id").toString()).toList(),"originalApproverId",submitted.get("originalApproverId").toString(),"agreedAt",submitted.get("agreedAt").toString(),"comment","已核验原同意人与申请范围一致","reason","有明确既有同意，仅补录此节点");}
    private Commands.Context evidenceContext(UUID step) {return context(admin,"WORKFLOW_STEP",step,"EVIDENCE_RECORD",((Number)db.required("SELECT row_version FROM workflow.step WHERE id=?",step).get("row_version")).intValue());}
    private UUID attachment(Map<String,Object> submitted) {return (UUID)((Map<?,?>)((List<?>)submitted.get("evidence")).getFirst()).get("id");}
    /** IT 补录后仍有下一必要节点，最终授权证明必须认可带完整证据的决定。 */
    @Test void evidenceDecisionContinuesRouteAndCannotGrantItFulltext() throws Exception {UUID step=consentStep();var submitted=submission(step);assertThrows(ApiFault.class,()->workflow.step(admin,step));assertTrue(consent.content(admin,attachment(submitted),UUID.randomUUID()).bytes().length>0);assertThrows(ApiFault.class,()->consent.content(actors.get(people.get("outsider")),attachment(submitted),UUID.randomUUID()));var ctx=evidenceContext(step);var body=decisionBody(submitted);var result=consent.decide(ctx,step,body);assertEquals("USED",result.get("state"));assertEquals(1,db.count("SELECT count(*) FROM ops.audit_event WHERE actor_id=? AND action='EVIDENCE_RECORD' AND resource_type='WORKFLOW_STEP' AND resource_id=? AND module='PLATFORM' AND record_kind='BUSINESS_EVENT'",admin.userId(),step));assertEquals(result.get("id"),consent.decide(ctx,step,body).get("id"));assertEquals(1,db.count("SELECT count(*) FROM workflow.decision WHERE step_id=? AND decision_mode='EVIDENCE_RECORD'",step));UUID flow=(UUID)db.required("SELECT instance_id FROM workflow.step WHERE id=?",step).get("instance_id");assertEquals("PENDING",db.required("SELECT state FROM workflow.instance WHERE id=?",flow).get("state"));approve(flow);UUID business=(UUID)db.required("SELECT business_id FROM workflow.instance WHERE id=?",flow).get("business_id");assertEquals(1,db.count("SELECT CASE WHEN workflow.approval_valid(?,'BORROW',?) THEN 1 ELSE 0 END",flow,business));assertEquals(2,db.count("SELECT count(*) FROM ops.business_notification WHERE source_kind='EVIDENCE_DECISION' AND source_id=?",result.get("decisionId")));}
    /** 旧任职、在线驳回和对象版本变动都不能被补录覆盖。 */
    @Test void reassignedApproverInvalidatesEvidence() throws Exception {UUID step=consentStep();var submitted=submission(step);db.update("UPDATE workflow.step SET assignment_ref=?,row_version=row_version+1 WHERE id=?",UUID.randomUUID(),step);assertThrows(ApiFault.class,()->consent.decide(evidenceContext(step),step,decisionBody(submitted)));assertEquals(0,db.count("SELECT count(*) FROM workflow.decision WHERE step_id=?",step));}
    @Test void rejectedStepCannotBeSupplemented() throws Exception {UUID step=consentStep();var submitted=submission(step);var node=db.required("SELECT * FROM workflow.step WHERE id=?",step);workflow.decide(context(actors.get(node.get("assignee_id")),"WORKFLOW_STEP",step,"DECIDE_STEP",((Number)node.get("row_version")).intValue()),step,Sql.map("result","REJECT","comment","不同意"));assertThrows(ApiFault.class,()->consent.decide(evidenceContext(step),step,decisionBody(submitted)));assertEquals("REJECT",db.required("SELECT result FROM workflow.decision WHERE step_id=?",step).get("result"));}
    @Test void quarantinedOrOtherContextObjectCannotBeSubmitted() throws Exception {UUID step=consentStep(),object=evidenceObject(step);var node=db.required("SELECT * FROM workflow.step WHERE id=?",step);db.update("UPDATE storage.object SET state='QUARANTINED' WHERE id=?",object);var body=Sql.map("originalApproverId",node.get("assignee_id").toString(),"agreedAt",Instant.now().toString(),"objectIds",List.of(object.toString()),"description","无效原件");assertThrows(ApiFault.class,()->consent.submit(new Commands.Context(applicant,UUID.randomUUID(),UUID.randomUUID(),"TEST BAD_EVIDENCE",null,1),step,body));assertEquals(0,db.count("SELECT count(*) FROM workflow.evidence_submission WHERE step_id=?",step));}
    @Test void replicaDamageBlocksContentAndApproval() throws Exception {UUID step=consentStep();var submitted=submission(step);var object=db.required("SELECT o.* FROM workflow.evidence e JOIN storage.object o ON o.id=e.object_id WHERE e.id=?",attachment(submitted));Path copy=Path.of(System.getenv("IMS_PLATFORM_STORAGE_SECONDARY")).resolve((String)object.get("storage_key"));byte[] original=Files.readAllBytes(copy);try{Files.writeString(copy,"合成副本异常");assertThrows(ApiFault.class,()->consent.content(admin,attachment(submitted),UUID.randomUUID()));assertThrows(ApiFault.class,()->consent.decide(evidenceContext(step),step,decisionBody(submitted)));assertEquals(0,db.count("SELECT count(*) FROM workflow.decision WHERE step_id=?",step));}finally{Files.write(copy,original);}}
    @Test void rejectionAndCancellationDoNotDecideBusiness() throws Exception {UUID step=consentStep();var submitted=submission(step);consent.close(context(admin,"WORKFLOW_STEP",step,"REJECT_EVIDENCE",1),(UUID)submitted.get("id"),Sql.map("reason","缺少完整同意范围"),true);assertEquals("PENDING",db.required("SELECT state FROM workflow.step WHERE id=?",step).get("state"));var next=submission(step);consent.close(new Commands.Context(applicant,UUID.randomUUID(),UUID.randomUUID(),"TEST CANCEL_EVIDENCE",null,1),(UUID)next.get("id"),Sql.map("reason","申请人撤回重整"),false);assertEquals(0,db.count("SELECT count(*) FROM workflow.decision WHERE step_id=?",step));}
    @Test void ordinaryApplicantCannotUseItQueueOrDecision() throws Exception {UUID step=consentStep();var submitted=submission(step);assertThrows(ApiFault.class,()->consent.queue(applicant,Map.of()));assertThrows(ApiFault.class,()->consent.decide(context(applicant,"WORKFLOW_STEP",step,"EVIDENCE_RECORD",1),step,decisionBody(submitted)));}
    /** 在线和补录并发只能产生一个决定，另一个得到明确冲突。 */
    @Test void onlineAndEvidenceDecisionsCompeteAtomically() throws Exception {UUID step=consentStep();var submitted=submission(step);var node=db.required("SELECT * FROM workflow.step WHERE id=?",step);var online=context(actors.get(node.get("assignee_id")),"WORKFLOW_STEP",step,"DECIDE_STEP",1);var recorded=evidenceContext(step);try(var pool=java.util.concurrent.Executors.newFixedThreadPool(2)){var start=new java.util.concurrent.CountDownLatch(1);var a=pool.submit(()->{start.await();try{workflow.decide(online,step,Sql.map("result","APPROVE","comment","本人在线同意"));return true;}catch(ApiFault e){return false;}});var b=pool.submit(()->{start.await();try{consent.decide(recorded,step,decisionBody(submitted));return true;}catch(ApiFault e){return false;}});start.countDown();assertNotEquals(a.get(30,java.util.concurrent.TimeUnit.SECONDS),b.get(30,java.util.concurrent.TimeUnit.SECONDS));}assertEquals(1,db.count("SELECT count(*) FROM workflow.decision WHERE step_id=?",step));}
    /** 交接预览和提交绑定完全相同的主体，接任人无需提前被分配档案员角色。 */
    private Map<String,Object> handoverBody(UUID department,Actor from,Actor to){var base=Sql.map("departmentId",department.toString(),"fromUserId",from.userId().toString(),"toUserId",to.userId().toString());var preview=continuity.preview(supervisor,base);base.put("previewDigest",preview.get("previewDigest"));base.put("approvalReference","TEST-HANDOVER");base.put("reason","已核对档案管理资料和在途实物责任");return base;}
    @Test void handoverMovesPendingAndWaitingWithoutPersonalGrantInheritance() throws Exception {UUID record=published("IMPORTANT",b);policy(record,false,List.of(archivistB.userId()));UUID batch=submitBorrow(applicant,List.of(record));var change=change(record,Sql.map("title","待交接更正"),"CORRECTION");Actor next=actors.get(people.get("outsider"));var body=handoverBody(b,archivistB,next);var ctx=context(supervisor,"DEPARTMENT",b,"HANDOVER_ARCHIVIST",null);var result=continuity.handover(ctx,body);assertEquals(1,db.count("SELECT count(*) FROM ops.audit_event WHERE actor_id=? AND action='HANDOVER_ARCHIVIST' AND resource_type='DEPARTMENT' AND resource_id=? AND module='PLATFORM' AND record_kind='BUSINESS_EVENT'",supervisor.userId(),b));assertEquals(result.get("id"),continuity.handover(ctx,body).get("id"));assertThrows(ApiFault.class,()->identity.background(archivistB.sessionId()));assertThrows(ApiFault.class,()->identity.background(next.sessionId()));assertEquals(next.userId(),db.required("SELECT managed_by FROM archive.catalog_change WHERE id=?",change.get("id")).get("managed_by"));assertEquals(1,db.count("SELECT count(*) FROM iam.user_role WHERE module='ARCHIVE' AND role_code='DEPARTMENT_ARCHIVIST' AND department_id=? AND state='ACTIVE'",b));assertEquals(0,db.count("SELECT count(*) FROM archive.access_grant WHERE user_id=?",next.userId()));assertEquals(1,db.count("SELECT count(*) FROM archive.access_grant WHERE user_id=? AND state='ACTIVE'",archivistB.userId()));assertTrue(db.count("SELECT count(*) FROM workflow.assignment_event WHERE handover_batch_id=?",result.get("id"))>0);refreshActors();approveBatch(batch);assertEquals("APPROVED",db.required("SELECT state FROM archive.borrow_batch WHERE id=?",batch).get("state"));}
