    @Test void transferRevokesSessionsGrantsAndPendingRequestsAndIsIdempotent() throws Exception {UUID record=published("GENERAL",b);policy(record,false,List.of(applicant.userId()));UUID usage=view(applicant,record),batch=submitBorrow(applicant,List.of(record));var body=Sql.map("targetDepartmentId",b.toString(),"approvalRef","TEST-TRANSFER","handoverNote","已核对资料归属和在途责任");var ctx=context(admin,"USER",applicant.userId(),"CHANGE_DEPARTMENT",((Number)applicant.user().get("rowVersion")).intValue());var result=continuity.transfer(ctx,applicant.userId(),body);assertEquals(1,db.count("SELECT count(*) FROM ops.audit_event WHERE actor_id=? AND action='CHANGE_DEPARTMENT' AND resource_type='USER' AND resource_id=? AND module='PLATFORM' AND record_kind='BUSINESS_EVENT'",admin.userId(),applicant.userId()));assertEquals(result.get("id"),continuity.transfer(ctx,applicant.userId(),body).get("id"));assertThrows(ApiFault.class,()->identity.background(applicant.sessionId()));assertThrows(ApiFault.class,()->reading.page(applicant,usage,1,UUID.randomUUID()));assertEquals(0,db.count("SELECT count(*) FROM archive.access_grant WHERE user_id=? AND state='ACTIVE'",applicant.userId()));assertEquals("WITHDRAWN",db.required("SELECT w.state FROM workflow.instance w JOIN archive.borrow_request q ON q.workflow_instance_id=w.id WHERE q.batch_id=?",batch).get("state"));assertEquals(1,db.count("SELECT count(*) FROM archive.borrow_batch WHERE id=?",batch));assertEquals(b,db.required("SELECT department_id FROM iam.user_account WHERE id=?",applicant.userId()).get("department_id"));}
    @Test void transferKeepsPhysicalResponsibilityAndBlocksUnhandedArchivist() throws Exception {UUID box=paperBox(b,"PAPER"),record=paperRecord(box,1),item=physical(record),batch=submitPaper(List.of(item),3);approveBatch(batch);UUID loan=loan(deliver(request(batch),item));continuity.transfer(context(admin,"USER",applicant.userId(),"CHANGE_DEPARTMENT",1),applicant.userId(),Sql.map("targetDepartmentId",b.toString(),"approvalRef","TEST-TRANSFER","handoverNote","本人仍承担在途原件归还责任"));assertEquals(applicant.userId(),db.required("SELECT borrower_id FROM archive.physical_loan WHERE id=?",loan).get("borrower_id"));assertEquals("IN_USE",db.required("SELECT state FROM archive.physical_loan WHERE id=?",loan).get("state"));assertThrows(ApiFault.class,()->continuity.transfer(context(admin,"USER",archivistA.userId(),"CHANGE_DEPARTMENT",1),archivistA.userId(),Sql.map("targetDepartmentId",b.toString(),"approvalRef","TEST","handoverNote","未交接")));}

    /** 人员编辑与独立转岗共享撤权和待办处理，编辑入口额外保留公司级任职。 */
    @Test void profileDepartmentChangeRevokesOldReadingAndPendingRequests() throws Exception {
        UUID record=published("GENERAL",b);policy(record,false,List.of(applicant.userId()));
        UUID usage=view(applicant,record),batch=submitBorrow(applicant,List.of(record));
        var body=Sql.map("name","已更正部门员工","departmentId",b,"changeReason","组织资料更正");
        int version=((Number)directory.user(applicant.userId()).get("rowVersion")).intValue();
        var ctx=context(admin,"USER",applicant.userId(),"UPDATE_USER",version);
        commands.run(ctx,body,"USER",applicant.userId(),"UPDATE_USER",()->admin.require("PLATFORM.USERS_MANAGE"),()->directory.updateUser(ctx,applicant.userId(),body),directory::user);
        assertEquals(b,directory.user(applicant.userId()).get("departmentId"));
        assertEquals(1,db.count("SELECT count(*) FROM iam.user_role WHERE user_id=? AND module='ARCHIVE' AND role_code='STAFF' AND state='ACTIVE'",applicant.userId()));
        assertEquals(0,db.count("SELECT count(*) FROM archive.access_grant WHERE user_id=? AND state='ACTIVE'",applicant.userId()));
        assertThrows(ApiFault.class,()->reading.page(applicant,usage,1,UUID.randomUUID()));
        assertEquals("WITHDRAWN",db.required("SELECT w.state FROM workflow.instance w JOIN archive.borrow_request q ON q.workflow_instance_id=w.id WHERE q.batch_id=?",batch).get("state"));
    }

