    @Test void existingConsentBeforeFormCreationIsAllowed() throws Exception {UUID step=consentStep(),object=evidenceObject(step);var node=db.required("SELECT * FROM workflow.step WHERE id=?",step);Instant agreed=Instant.parse(db.required("SELECT valid_from FROM iam.department_manager WHERE id=?",node.get("assignment_ref")).get("valid_from").toString()).plusMillis(1);var submitted=consent.submit(new Commands.Context(applicant,UUID.randomUUID(),UUID.randomUUID(),"TEST PREEXISTING_CONSENT",null,1),step,Sql.map("originalApproverId",node.get("assignee_id").toString(),"agreedAt",agreed.toString(),"objectIds",List.of(object.toString()),"description","填单之前已经明确同意固定版本与期限"));assertEquals("USED",consent.decide(evidenceContext(step),step,decisionBody(submitted)).get("state"));}
