    @Test void audioEvidenceUsesRealInspectionAndRejectsMalformedContent() throws Exception {UUID step=consentStep();for(boolean valid:List.of(true,false)){byte[] bytes=valid?AudioMediaCheckTest.wav():"not-a-wave".getBytes(java.nio.charset.StandardCharsets.UTF_8);String hash=HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(bytes));UUID upload=(UUID)uploads.create(applicant,Sql.map("module","ARCHIVE","businessContextId",step.toString(),"purpose","EVIDENCE","originalName","既有同意录音.wav","expectedSize",bytes.length,"expectedSha256",hash,"expectedMediaType","application/octet-stream"),UUID.randomUUID(),UUID.randomUUID()).get("uploadId");uploads.part(applicant,upload,1,"bytes 0-"+(bytes.length-1)+"/"+bytes.length,bytes.length,hash,new ByteArrayInputStream(bytes),UUID.randomUUID());UUID job=(UUID)uploads.complete(applicant,upload,Sql.map("partCount",1,"finalSha256",hash),UUID.randomUUID(),UUID.randomUUID()).get("jobId");assembly.assemble(applicant,job,UUID.randomUUID());inspection.inspect(applicant,job,UUID.randomUUID());assertEquals(valid?"COMPLETE":"REJECTED",uploads.get(applicant,upload).get("state"));}}

